"""rookery_views — the generated files of `rookery up`: workspace files and ROOKERY.md (D7, D15)."""
import datetime
import json
import os
import re
import stat
import tempfile

import cli_init
import turn_block


class LinkRefused(Exception):
    """A generated file would go through a link or outside its base. Carries the path."""

    def __init__(self, path):
        self.path = path
        super().__init__(f"{path} is a link. Rookery does not follow links in its generated files. "
                         "Remove the link, then run rookery up again.")


def _write_generated(path, text, base):
    """Write a generated file below base. Refuse (LinkRefused) when any component from base down to the
    file is a link or the folder resolves outside base. Writes a temp file and os.replace()s it, so a
    link is never followed and never replaced."""
    path = os.path.abspath(path)
    base = os.path.abspath(base)
    rel = os.path.relpath(path, base)
    if rel == ".." or rel.startswith(".." + os.sep) or os.path.isabs(rel):
        raise LinkRefused(path)
    cur = base
    for part in rel.split(os.sep):
        cur = os.path.join(cur, part)
        if os.path.islink(cur):
            raise LinkRefused(cur)
    d = os.path.dirname(path)
    os.makedirs(d, exist_ok=True)
    rb = os.path.realpath(base)
    if os.path.commonpath([os.path.realpath(d), rb]) != rb:
        raise LinkRefused(path)
    tmp = None
    try:
        fd, tmp = tempfile.mkstemp(dir=d, prefix=".tmp-", suffix=os.path.splitext(path)[1])
        with os.fdopen(fd, "w", encoding="utf-8", errors="surrogateescape", newline="") as fh:
            fh.write(text)
            fh.flush()
            os.fsync(fh.fileno())
        um = os.umask(0)
        os.umask(um)
        os.chmod(tmp, 0o666 & ~um)
        if os.path.islink(path):
            raise LinkRefused(path)
        os.replace(tmp, path)
        tmp = None
    finally:
        if tmp:
            try:
                os.unlink(tmp)
            except OSError:
                pass
    return path


def _stamp(command):
    t = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    return f"<!-- generated by rookery {command} at {t}; do not edit -->\n\n"


def _bullets(items):
    return "".join(f"- {x}\n" for x in items)


def _default_scope(role):
    if role == "writer":
        return (["change files in the worktree of this agent", "write notes under the runs folder of this agent"],
                ["change files outside the worktree of this agent", "change the files of another agent"])
    return (["read files and report the findings"],
            ["edit files", "run the server", "change the files of another agent"])


def _scope(agent):
    sc = agent.get("scope") or {}
    d_does, d_not = _default_scope(agent.get("role"))
    return (sc.get("does") or d_does), (sc.get("does_not") or d_not)


def _persona(agent):
    return agent.get("persona") or (
        f"You are {agent['name']}. You work as a {agent.get('role', 'reader')} in a team of agents. "
        "Do the task you get. Report what you did.")


def _persona_md(agent):
    return (f"# Persona of {agent['name']}\n\n{_persona(agent)}\n\n## Rules\n\n"
            + _bullets([
                "Read the roster in ROOKERY.md and _directory/INDEX.md before you ask the user.",
                "Ask another agent when it can answer. Ask the user only when no agent can.",
                "Stay inside your scope card.",
                "Send mail with the Rookery commands and the rookery block. Use no other way.",
                "Do not poll for mail. Rookery tells you when mail arrives.",
            ]))


def _card(a):
    does, not_does = _scope(a)
    return (f"### {a['name']}\n\n- Role: {a.get('role', 'reader')}\n"
            f"- Does: {'; '.join(does)}\n- Does NOT do: {'; '.join(not_does)}\n")


def _scope_md(agent, team):
    does, not_does = _scope(agent)
    out = (f"# Scope card of {agent['name']}\n\n## Does\n\n{_bullets(does)}\n"
           f"## Does NOT do\n\n{_bullets(not_does)}\n## Other agents in this team\n\n")
    others = [a for a in team.get("agents", []) if a["name"] != agent["name"]]
    if not others:
        return out + "None. You work alone.\n"
    return out + "\n".join(_card(a) for a in others)


def _body_md(agent, session, host_import=None, rules_link=False):
    return f"""# {agent['name']}

You are **{agent['name']}**. Your agent ID is `{agent['agent_id']}`.
You work in the session `{session['name']}`. Your role is {agent.get('role', 'reader')}. Your harness is {agent.get('harness', 'claude')}.

## Mail

Rookery gives you durable mail. Use these commands only.

- Run `rookery inbox` to read your unread mail. It marks nothing as read.
- Run `rookery peek` to look at your mail and change nothing.
- Run `rookery ack ID ...` to mark mail as read. The last line of the inbox output shows the command.
- Run `rookery send TO "SAY"` to send one mail now.

To send mail at the end of a turn, end your final message with one fenced block. The info string is `rookery`.
The block holds one JSON object. Put nothing after it. Write no block when you have nothing to send.
You must set `to`, `task`, `kind`, `say` and `status`. Run `rookery identity show` if you need your name.
The full contract is in the Rookery skill.

```rookery
{{"to": "NAME", "task": "TASK-ID", "kind": "status", "say": "TEXT", "status": "in-progress"}}
```

Do not poll. Do not sleep. Do not schedule inbox checks.

## Where to look

- `ROOKERY.md` at the Rookery root says what each root folder holds.
- `CONTEXT.md` in this folder says how you stage your work.
- `_config/` in this folder holds your persona and your scope card.
""" + _rules_md(host_import, rules_link)


def _rules_md(host_import, rules_link):
    out = ""
    if host_import:
        out += f"\n## Project rules\n\n@{host_import}\n"
    if rules_link:
        out += "\n## Project rules\n\nRead `HOST_RULES.md` in this folder. It holds the rules of the host repo.\n"
    return out


def _context_md(agent):
    return f"""# How {agent['name']} stages work

Keep each task in its own folder: `runs/<TASK-ID>/`. It has three stage folders.

- `01_intake`: the task, the mail and the files you got.
- `02_work`: your notes and drafts.
- `03_report`: the result that you hand over.

## HANDOFF.md

At the end of each turn, overwrite `runs/<TASK-ID>/HANDOFF.md`. Give it these four sections.

- `Last thing I did`
- `State now`
- `What is left`
- `Open threads`

A new session of you reads this file first. Write it so that a reader with no memory can continue.

Rookery never writes inside `runs/`, `outbox/` or `state/`. Do not edit the other files in this folder.
Rookery writes them again at the next start.
"""


def host_rules_file(host):
    """The host repo's rules file for a reader: AGENTS.md, else CLAUDE.md, else None."""
    for n in ("AGENTS.md", "CLAUDE.md"):
        p = os.path.join(host, n) if host else None
        if p and os.path.isfile(p):
            return p
    return None


def _host_rules_link(ws, host, notes):
    """Make HOST_RULES.md a symlink to the host rules file. Return True when it is in place.
    A regular file that a person put there stays, with a note."""
    target = host_rules_file(host)
    link = os.path.join(ws, "HOST_RULES.md")
    if target is None:
        if os.path.islink(link):
            os.remove(link)
        return False
    if os.path.lexists(link) and not os.path.islink(link):
        if notes is not None:
            notes.append(f"{os.path.basename(ws)}: HOST_RULES.md is a file that you made, so Rookery kept it")
        return False
    if os.path.islink(link):
        os.remove(link)
    os.symlink(os.path.abspath(target), link)
    return True


def workspace_files(root, session, agent, team, host, command="up", notes=None):
    """Write the generated files of one agent workspace. Return the workspace path.
    Never writes inside runs/, outbox/ or state/, and never touches HANDOFF.md.
    For a reader, link the host rules (FR-012); a line is added to `notes` when it cannot."""
    ws = turn_block.workspace(root, session["name"], agent["name"])
    stamp = _stamp(command)
    reader = agent.get("role") != "writer"
    imp = link = None
    if reader:
        link = _host_rules_link(ws, host, notes)
        hc = os.path.join(host, "CLAUDE.md") if host else None
        imp = os.path.abspath(hc) if hc and os.path.isfile(hc) else None
        if notes is not None and host_rules_file(host) is None:
            notes.append(f"{agent['name']}: the host repo has no CLAUDE.md or AGENTS.md")
    body = _body_md(agent, session, imp)
    agents_body = _body_md(agent, session, None, link)
    persona = _persona_md(agent)
    scope = _scope_md(agent, team)
    files = {
        "CLAUDE.md": body,
        "AGENTS.md": agents_body,
        "CONTEXT.md": _context_md(agent),
        "_config/persona.md": persona,
        "_config/scope-card.md": scope,
        "_config/system-prompt.md": persona + "\n" + scope,
    }
    for rel, text in files.items():
        _write_generated(os.path.join(ws, rel), stamp + text, ws)
    for d in ("runs", "outbox", "state"):
        os.makedirs(os.path.join(ws, d), exist_ok=True)
    return ws


def rookery_md(root, command="up"):
    """Write ROOKERY.md at the root (L0 routing). Never writes CLAUDE.md or AGENTS.md."""
    text = """# Rookery root

This folder is the shared root of one project. Each folder has one job.

- `agents/`: one workspace for each agent, as `agents/<session>/<name>/`.
- `wt/`: the git worktrees of the writers.
- `_directory/`: who is here. Read `_directory/INDEX.md` for the roster.
- `_teams/`: one file for each session, with its task and members.
- `_threads/`: one line for each mail thread. It holds no mail body.
- `_mail/`: the metadata of held and quarantined mail. It holds no mail body.
- `logs/`: the logs of Rookery.
- `postmaster/`: the state of the postmaster.

Read your own `CLAUDE.md` in your workspace first. Read the roster before you ask the user.
Use the `rookery` commands to read and send mail.
"""
    path = os.path.join(root, "ROOKERY.md")
    _write_generated(path, _stamp(command) + text, root)
    return path


def _committed_commands(repo):
    """The first Rookery handler per hook event in the repo's committed .claude/settings.json, as
    (matcher group, whole handler object). A missing or invalid file gives {}."""
    try:
        with open(os.path.join(repo, ".claude", "settings.json"), encoding="utf-8") as fh:
            hooks = json.load(fh).get("hooks")
    except (OSError, ValueError, AttributeError):
        return {}
    found = {}
    if not isinstance(hooks, dict):
        return found
    for event, _sub in cli_init.HOOK_EVENTS:
        groups = hooks.get(event)
        for g in groups if isinstance(groups, list) else []:
            for h in (g.get("hooks") if isinstance(g, dict) and isinstance(g.get("hooks"), list) else []):
                if event not in found and cli_init._is_rookery(h):
                    found[event] = (g, h)
    return found


def settings_json(path, project, repo=None, base=None):
    """Write the hooks file `_config/settings.json` (D8), built fresh on every run: an old file is
    replaced, so a hand edit does not survive. With a repo that has the hooks committed, each event copies
    the whole committed handler (and its group matcher), so Claude Code runs the same handler once.
    Never writes the repo file or ~/.claude/settings.json."""
    with tempfile.TemporaryDirectory() as tmp:
        scratch = os.path.join(tmp, "settings.json")
        cli_init.merge_hooks(scratch, project, with_permissions=True)
        with open(scratch, encoding="utf-8") as fh:
            data = json.load(fh)
    committed = _committed_commands(repo) if repo else {}
    for event, (cgroup, chandler) in committed.items():
        for g in data["hooks"][event]:
            for i, h in enumerate(g["hooks"]):
                if cli_init._is_rookery(h):
                    g["hooks"][i] = json.loads(json.dumps(chandler))
                    if "matcher" in cgroup:
                        g["matcher"] = cgroup["matcher"]
    _tool_handlers(data, project)
    _write_generated(path, json.dumps(data, indent=2, ensure_ascii=False) + "\n",
                     base or os.path.dirname(os.path.abspath(path)))
    return path


_TOOL_HANDLERS = (("PreToolUse", "Write|Edit|MultiEdit|NotebookEdit", "guard"), ("PostToolUse", "Bash", "watch"))
_TOOL_OURS = re.compile(r"(?:\S*/)?rookery hook (guard|watch) --project \S+")


def _tool_handlers(data, project):
    """Add the guard (PreToolUse) and watch (PostToolUse) handlers (T019) to the settings object."""
    hooks = data.setdefault("hooks", {})
    for event, matcher, sub in _TOOL_HANDLERS:
        cmd = f"rookery hook {sub} --project {project}"
        groups = hooks.setdefault(event, [])
        done = False
        for g in groups:
            for h in g.get("hooks", []):
                m = isinstance(h.get("command"), str) and _TOOL_OURS.fullmatch(h["command"].strip())
                if m and m.group(1) == sub:
                    h["command"] = cmd
                    done = True
        if not done:
            groups.append({"matcher": matcher, "hooks": [{"type": "command", "command": cmd}]})


# --- views read from the database (T017, D15). SELECT only: nothing here writes a row or marks mail read.

def _cell(v, limit=80):
    """One table cell: one line, no pipe, short."""
    s = " ".join(str(v if v is not None else "-").split()).replace("|", "/")
    return (s[:limit] or "-")


def _table(head, rows):
    out = "| " + " | ".join(head) + " |\n|" + "---|" * len(head) + "\n"
    return out + "".join("| " + " | ".join(_cell(c) for c in r) + " |\n" for r in rows)


def _iso(epoch):
    try:
        return datetime.datetime.fromtimestamp(int(epoch), datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    except (TypeError, ValueError, OverflowError, OSError):
        return "-"


def _turn_status(root, session, name):
    try:
        with open(os.path.join(turn_block.workspace(root, session, name), "state", "turn.json"),
                  encoding="utf-8") as fh:
            state = json.load(fh).get("state")
    except (OSError, ValueError, AttributeError, KeyError):
        return "none"
    return state if state in ("idle", "busy") else "none"


def _newest_run(root, session, name):
    runs = os.path.join(root, "agents", session, name, "runs")
    best = None
    try:
        for e in os.scandir(runs):
            if e.is_dir():
                m = e.stat().st_mtime
                if best is None or (m, e.name) > best:
                    best = (m, e.name)
    except OSError:
        return None
    return best[1] if best else None


def _names(conn):
    """agent_id -> identity name, for mail rows that carry agent IDs."""
    return {r[0]: r[1] for r in conn.execute("SELECT agent_id, name FROM identities")}


def _write(root, rel, text, command):
    path = os.path.join(root, *rel.split("/"))
    _write_generated(path, _stamp(command) + text, root)
    return path


def directory(conn, root, command="regen"):
    """_directory/INDEX.md, ports.md, claims.md. Returns the INDEX path."""
    rows = []
    q = conn.execute(
        "SELECT i.agent_id, i.name, s.name AS session, u.harness, u.role, u.task_id "
        "FROM identities i JOIN rookery_sessions s ON s.session_id=i.session_id "
        "LEFT JOIN up_agents u ON u.agent_id=i.agent_id "
        "WHERE s.state='open' ORDER BY s.name, i.name").fetchall()
    for r in q:
        b = conn.execute("SELECT kind, value FROM bindings WHERE owner_type='identity' AND owner_id=? "
                         "ORDER BY created_at DESC, rowid DESC LIMIT 1", (r["agent_id"],)).fetchone()
        try:
            run = _newest_run(root, r["session"], r["name"])
        except ValueError:
            run = None
        try:
            status = _turn_status(root, r["session"], r["name"])
        except ValueError:
            status = "none"
        rows.append((r["name"], r["harness"] or "-", f"{b['kind']}:{b['value']}" if b else "-", status,
                     run or r["task_id"] or "-", r["role"] or "-", r["session"]))
    index = _write(root, "_directory/INDEX.md",
                   "# Directory\n\nOne row for each agent of the open sessions.\n\n" +
                   _table(["name", "harness", "pane", "status", "current task", "role", "team"], rows), command)
    ports = conn.execute(
        "SELECT i.name, p.name, p.port FROM ports p LEFT JOIN identities i ON i.agent_id=p.agent_id "
        "ORDER BY i.name, p.name").fetchall()
    _write(root, "_directory/ports.md", "# Ports\n\n" + _table(
        ["agent", "name", "port"], [(r[0] or "-", r[1], r[2]) for r in ports]), command)
    claims = conn.execute(
        "SELECT s.name, i.name, c.pattern FROM claims c "
        "LEFT JOIN rookery_sessions s ON s.session_id=c.session_id "
        "LEFT JOIN identities i ON i.agent_id=c.agent_id WHERE c.active=1 "
        "ORDER BY s.name, i.name, c.pattern").fetchall()
    _write(root, "_directory/claims.md", "# Claims\n\nActive claims only.\n\n" + _table(
        ["session", "agent", "pattern"], [(r[0] or "-", r[1] or "-", r[2]) for r in claims]), command)
    return index


def teams(conn, root, session, team, command="up"):
    """_teams/<session>.md: the task, the acceptance criteria and the members."""
    import rookery_identity
    name = rookery_identity.safe_name(session["name"], "session name")
    members = conn.execute(
        "SELECT i.name, u.role, u.harness FROM identities i LEFT JOIN up_agents u ON u.agent_id=i.agent_id "
        "WHERE i.session_id=? ORDER BY i.name", (session["session_id"],)).fetchall()
    text = f"# Team {name}\n\n## Task\n\n{(team or {}).get('task') or '-'}\n\n## Acceptance criteria\n\n"
    crit = (team or {}).get("acceptance") or []
    text += (_bullets(crit) if crit else "- none\n")
    text += "\n## Members\n\n" + _table(["name", "role", "harness"],
                                         [(r[0], r[1] or "-", r[2] or "-") for r in members])
    return _write(root, f"_teams/{name}.md", text, command)


def threads(conn, root, command="regen"):
    """_threads/INDEX.md: one line for each group of mail with the same topic, sender and recipient.
    Metadata only. The body column is never read."""
    ids = _names(conn)
    rows = conn.execute(
        "SELECT topic, sender, recipient, COUNT(*) AS n, MAX(created_at) AS last, MAX(id) AS last_id "
        "FROM inbox GROUP BY session_id, topic, sender, recipient ORDER BY last DESC, last_id DESC").fetchall()
    out = []
    for r in rows:
        st = conn.execute("SELECT status FROM inbox WHERE id=?", (r["last_id"],)).fetchone()[0]
        out.append((r["topic"] or "-", ids.get(r["sender"], r["sender"]), ids.get(r["recipient"], r["recipient"]),
                    r["n"], _iso(r["last"]), st))
    return _write(root, "_threads/INDEX.md",
                  "# Threads\n\nOne line for each thread. No mail body is here.\n\n" +
                  _table(["thread", "sender", "recipient", "mails", "time", "state"], out), command)


def _safe_file(s):
    return "".join(c if (c.isalnum() or c in "._-") else "_" for c in str(s or "unknown"))[:64].strip(".") or "unknown"


def _is_generated(path):
    """True when the file starts with the line that Rookery writes on every generated view."""
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            return fh.readline().startswith("<!-- generated by rookery ")
    except OSError:
        return False


def mail_mirror(conn, root, command="regen"):
    """_mail/quarantine/<reason>/<id>.md and _mail/review/<id>.md: the metadata of each quarantined,
    held or escalated row. No body. Files of rows that left these states are removed. Returns the paths written."""
    ids = _names(conn)
    want = {}
    q = conn.execute(
        "SELECT m.id, m.sender, m.recipient, m.topic, m.status, m.reason, m.decided_by, m.created_at, "
        "m.decided_at, s.name AS session FROM inbox m LEFT JOIN rookery_sessions s ON s.session_id=m.session_id "
        "WHERE m.status IN ('quarantined','held','escalated') ORDER BY m.id").fetchall()
    for r in q:
        rel = (f"_mail/quarantine/{_safe_file(r['reason'])}/{int(r['id'])}.md" if r["status"] == "quarantined"
               else f"_mail/review/{int(r['id'])}.md")
        text = f"# Mail {int(r['id'])}\n\nState: {r['status']}. The body is not here.\n\n" + _bullets([
            f"id: {int(r['id'])}", f"session: {_cell(r['session'])}",
            f"sender: {_cell(ids.get(r['sender'], r['sender']))}",
            f"recipient: {_cell(ids.get(r['recipient'], r['recipient']))}",
            f"topic: {_cell(r['topic'])}", f"reason: {_cell(r['reason'])}",
            f"decided by: {_cell(r['decided_by'])}",
            f"time: {_iso(r['decided_at'] or r['created_at'])}"])
        want[os.path.normpath(os.path.join(root, *rel.split("/")))] = text
    mail = os.path.join(root, "_mail")
    for sub in ("quarantine", "review"):
        if os.path.islink(os.path.join(mail, sub)) or os.path.islink(mail):
            continue   # never walk or delete through a link
        for d, _dn, fs in os.walk(os.path.join(mail, sub)):
            for f in fs:
                p = os.path.normpath(os.path.join(d, f))
                if f.endswith(".md") and p not in want and not os.path.islink(p) and _is_generated(p):
                    os.remove(p)   # a stale view Rookery wrote; a file a person made stays
    for p, text in want.items():
        _write_generated(p, _stamp(command) + text, root)
    return sorted(want)
